CREATE TABLE IF NOT EXISTS agendamentos (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, tel text, tel_documentos text, cpf text, modalidade text DEFAULT 'chat', horario_agendado timestamp without time zone, payment_id text, status text DEFAULT 'pendente', criado_em timestamp without time zone DEFAULT now(), lembrete_enviado boolean DEFAULT false, email text, lembrete_paciente_enviado boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS especialistas (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, nome_exibicao text, especialidade text, crm text, uf text, valor_consulta numeric, foto_url text, bio text, ativo boolean DEFAULT true, created_at timestamp without time zone DEFAULT now(), email text, visivel boolean DEFAULT true, disponibilidade jsonb, precisa_trocar_senha boolean DEFAULT false, senha_hash text, rqe text, cpf_medico text, data_nascimento_medico text, senha_reset_hash text, senha_reset_expira_em timestamp with time zone, senha_reset_solicitado_em timestamp with time zone, senha_reset_tentativas integer DEFAULT 0, senha_alterada_em timestamp with time zone);
CREATE TABLE IF NOT EXISTS eventos_funil (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, modulo text, evento text, pagina text, profissional_id integer, session_id text, metadata jsonb DEFAULT '{}'::jsonb, criado_em timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS fila_atendimentos (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, tel text, cpf text, tipo text DEFAULT 'whatsapp', triagem text, status text DEFAULT 'aguardando', medico_id integer, medico_nome text, criado_em timestamp without time zone DEFAULT now(), assumido_em timestamp without time zone, encerrado_em timestamp without time zone, status_atendimento text, documentos_emitidos text, meet_link text, tel_documentos text, idade text, sexo text, alergias text, cronicas text, medicacoes text, queixa text, data_nascimento text, prontuario text, solicita text, agendamento_id integer, horario_agendado timestamp without time zone, email text, aprovacao_token text, pagamento_status text DEFAULT 'pendente', pagbank_order_id text, pagamento_confirmado_em timestamp with time zone, efi_charge_id text, prioridade_liberada_em timestamp with time zone, pagamento_metodo text, anexos_urls jsonb DEFAULT '{}'::jsonb, endereco_envio jsonb, frete_valor numeric, frete_modalidade text, frete_servico_id text, frete_prazo_dias integer, questionario jsonb, ads_gclid text, ads_gbraid text, ads_wbraid text, ads_utm jsonb DEFAULT '{}'::jsonb, ads_landing_url text, ads_referrer text, ads_checkout_session_id text, ads_user_agent text, ads_capturado_em timestamp with time zone, confirmado_pageview_em timestamp with time zone, confirmado_has_ads_id boolean, confirmado_href text, google_ads_offline_status text, google_ads_offline_enviado_em timestamp with time zone, google_ads_offline_tentativas integer DEFAULT 0, google_ads_offline_job_id text, google_ads_offline_erro text, google_ads_offline_order_id text, atendimento_para_terceiro boolean DEFAULT false, pagador_nome text, pagador_cpf text, pagador_email text, pagbank_qr_text text, pagbank_qr_expira_em timestamp with time zone, categoria_atendimento text DEFAULT 'clinico', especialidade_solicitada text, valor_cobrado_centavos integer DEFAULT 4990, fallback_disponivel_em timestamp with time zone, fallback_decisao text, fallback_decidido_em timestamp with time zone, reembolso_status text, reembolso_valor_centavos integer DEFAULT 0, reembolso_processado_em timestamp with time zone, reembolso_erro text, prioridade_medico_id integer, prioridade_ate timestamp with time zone, prioridade_geral_notificada_em timestamp with time zone, mostrar_avaliacao_google boolean DEFAULT false, google_ads_margem_status text, google_ads_margem_enviado_em timestamp with time zone, google_ads_margem_tentativas integer DEFAULT 0, google_ads_margem_job_id text, google_ads_margem_erro text, google_ads_margem_order_id text, google_ads_margem_valor_centavos integer, push_assumido_paciente_em timestamp with time zone, renovacao_receita_pronta_em timestamp with time zone, renovacao_receita_url text, renovacao_receita_nome text, renovacao_push_pronta_em timestamp with time zone, renovacao_enviada_em timestamp with time zone, renovacao_rastreio text, ads_fbclid text, ads_first_touch jsonb, ads_last_touch jsonb, ads_conversion_touch jsonb, origem_plataforma text, app_install_id text, app_attribution_id text, cliente_novo boolean, customer_type text, customer_type_classificado_em timestamp with time zone, stripe_checkout_session_id text, stripe_payment_intent_id text, conta_paciente_id integer);
CREATE TABLE IF NOT EXISTS medicos (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, email text, senha_hash text, crm text, status_online boolean DEFAULT false, ativo boolean DEFAULT true, created_at timestamp without time zone DEFAULT now(), role text DEFAULT 'medico', status text DEFAULT 'pendente', uf text, telefone text, especialidade text, nome_exibicao text, cnpj text, tem_assinatura_digital boolean DEFAULT false, provedor_assinatura text, tem_memed boolean DEFAULT false, memed_email text, cpf_medico text, data_nascimento_medico text, memed_token text, memed_external_id text, precisa_trocar_senha boolean DEFAULT false, senha_reset_hash text, senha_reset_expira_em timestamp with time zone, senha_reset_solicitado_em timestamp with time zone, senha_reset_tentativas integer DEFAULT 0, senha_alterada_em timestamp with time zone);
CREATE TABLE IF NOT EXISTS mensagens (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, atendimento_id integer, autor text, autor_id integer, texto text, criado_em timestamp without time zone DEFAULT now(), arquivo_url text, arquivo_tipo text, arquivo_nome text, reply_to_id bigint, lido_paciente_em timestamp with time zone, lido_medico_em timestamp with time zone, push_paciente_em timestamp with time zone, web_push_paciente_em timestamp with time zone, web_push_medico_em timestamp with time zone);
CREATE TABLE IF NOT EXISTS pacientes (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, email text, senha_hash text, cpf text, tel text, created_at timestamp without time zone DEFAULT now(), data_nascimento text);
CREATE TABLE IF NOT EXISTS psicologos (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, nome_exibicao text, email text, senha_hash text, crp text, uf text, telefone text, abordagem text, focos text, valor_sessao text, atende_online boolean DEFAULT true, tem_avaliacao boolean DEFAULT false, valor_avaliacao text, apresentacao text, disponibilidade text, status text DEFAULT 'pendente', ativo boolean DEFAULT false, created_at timestamp without time zone DEFAULT now(), foto_url text, formulario_url text, valor_atualizado_em timestamp without time zone, visivel boolean DEFAULT true, sala_meet text);

